package bo.soboce.comedor;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.google.zxing.integration.android.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** The master manages credentials; ordinary users only sign in. */
public final class StaffActivity extends Activity {
 private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private PeerConfig config;private StaffAccess auth;private String company;private LinearLayout page;private TextView state;private boolean busy;private CancellationSignal biometric;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);try{
  company=getIntent().getStringExtra("company");if(company==null)company=Companies.current(this);config=new PeerConfig(new Vault(this,company).read("peerConfig"));auth=StaffAccess.attach(this,config);PeerConfig.require(auth!=null,"Esta instalación no tiene configuradas las cuentas.");
  if(auth.ready())finishLogin();else login();
 }catch(Exception e){screen("Acceso del personal","Los trabajadores y las entregas se conservan. No borres los datos.");error(e.getMessage());button("Reintentar",this::recreate);button("Volver",this::finish);}}
 private void reload()throws Exception {auth=new StaffAccess(this,config);}
 private void screen(String title,String subtitle){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Design.BG);page=Design.column(this);page.setPadding(Design.dp(this,24),Design.dp(this,26),Design.dp(this,24),Design.dp(this,26));scroll.addView(page);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(0,in.getSystemWindowInsetTop(),0,in.getSystemWindowInsetBottom());return in;});label((company==null?"COLBERT":company.toUpperCase(Locale.ROOT))+" / ACCESO PERSONAL",12,Design.BLUE);label(title,28,Design.INK);label(subtitle,15,Design.MUTED);state=label("",14,Design.RED);}
 private TextView label(String text,int size,int color){TextView v=Design.text(this,text,size,color,size>=20);v.setPadding(0,Design.dp(this,8),0,Design.dp(this,8));page.addView(v);return v;}
 private EditText field(String hint,String text,boolean pin){EditText v=new EditText(this);v.setHint(hint);v.setContentDescription(hint);v.setText(text);v.setSingleLine(true);if(pin){v.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);v.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6)});}page.addView(v,new LinearLayout.LayoutParams(-1,Design.dp(this,58)));return v;}
 private EditText password(String hint){EditText v=field(hint,"",false);v.setSaveEnabled(false);v.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);v.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(128)});return v;}
 private void button(String title,Runnable run){Button b=Design.button(this,title,Design.BLUE,Color.WHITE,()->{if(!busy)run.run();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Design.dp(this,10);page.addView(b,p);}
 private void error(String message){if(state!=null)state.setText(message==null?"No se pudo completar. Vuelve a intentarlo.":message);}
 interface Work {JSONObject run()throws Exception;}
 private void task(Work work,java.util.function.Consumer<JSONObject> done){if(busy)return;busy=true;state.setText("Comprobando acceso…");executor.execute(()->{JSONObject reply=null;String problem=null;try{reply=work.run();}catch(Exception e){problem=e instanceof java.io.IOException?"No se confirmó la conexión. Tus datos y permisos guardados se conservan.":e.getMessage();}JSONObject r=reply;String p=problem;runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;if(p!=null)error(p);else{state.setText("");done.accept(r);}});});}
 private void login(){try{
  reload();screen("Iniciar sesión","Escribe el usuario y la contraseña que te dio la administradora principal.");
  label("Usuario",13,Design.BLUE);EditText name=field("Usuario",auth.username(),false);label("Contraseña",13,Design.BLUE);EditText pass=password("Contraseña");
  button("Entrar",()->{String user=name.getText().toString(),secret=pass.getText().toString();pass.setText("");task(()->{auth=StaffAccess.loginPassword(this,config,user,secret);return new JSONObject();},r->finishLogin());});
  if(fingerprintAvailable()&&auth.biometricAllowed())button("Entrar con huella",this::biometric);
  button("Olvidé mi contraseña",()->new AlertDialog.Builder(this).setTitle("Restablecer contraseña").setMessage("La cuenta maestra puede cambiar tu contraseña desde Encargados y permisos. Luego entra con la nueva contraseña y conexión a internet. Tus consumos se conservan.").setPositiveButton("Entendido",null).show());
  label("El primer ingreso en este celular necesita internet. Después puedes entrar con tu acceso guardado. Entrar en otro celular reemplaza al anterior cuando reciba la actualización.",13,Design.MUTED);
  button("Cambiar empresa",this::switchCompany);
  if(hasLegacyProfiles())button("Acceso anterior con PIN",this::legacyLogin);
  button("Acceso privado de la cuenta maestra",this::masterSetup);button("Volver",this::finish);
 }catch(Exception e){error(e.getMessage());}}
 private boolean hasLegacyProfiles()throws Exception {JSONArray all=auth.profiles();for(int i=0;i<all.length();i++){JSONObject p=all.getJSONObject(i);String cert=auth.companyVault.get("staffCert:"+p.getString("profile"));if(!p.optString("intent").equals("password")&&(cert.isEmpty()||StaffProtocol.grant(cert,config).optString("username").isEmpty()))return true;}return false;}
 private void legacyLogin(){try{screen("Acceso anterior con PIN","Conservamos el acceso previo durante la migración. La cuenta maestra debe asignar usuario y contraseña a cada cuenta existente.");JSONArray all=auth.profiles();for(int i=0;i<all.length();i++){JSONObject p=all.getJSONObject(i);String id=p.getString("profile"),cert=auth.companyVault.get("staffCert:"+id);if(p.optString("intent").equals("password")||(!cert.isEmpty()&&!StaffProtocol.grant(cert,config).optString("username").isEmpty()))continue;button("Entrar · "+p.getString("name"),()->{try{auth.select(id);reload();pin();}catch(Exception e){error(e.getMessage());}});}button("Volver al login",this::login);}catch(Exception e){error(e.getMessage());}}
 private void pin(){try{screen("Hola, "+auth.local().getString("name"),"Usa tu PIN anterior. La administradora principal podrá configurar tu usuario y contraseña sin crear otra cuenta.");EditText input=field("PIN de 6 números","",true);button("Entrar",()->{String value=input.getText().toString();input.setText("");task(()->{auth.unlock(value);try{auth.refresh(true);}catch(java.io.IOException ignored){}return new JSONObject();},r->{if(!auth.username().isEmpty()){StaffAccess.lock();login();error("Tu cuenta ya tiene usuario y contraseña. Entra con esos datos.");}else finishLogin();});});button("Volver al login",this::login);}catch(Exception e){error(e.getMessage());}}
 private boolean fingerprintAvailable(){if(Build.VERSION.SDK_INT<28)return false;try{android.hardware.fingerprint.FingerprintManager f=getSystemService(android.hardware.fingerprint.FingerprintManager.class);return f!=null&&f.isHardwareDetected()&&f.hasEnrolledFingerprints();}catch(SecurityException unavailable){return false;}}
 @android.annotation.TargetApi(28) private void biometric(){if(!fingerprintAvailable()||!auth.biometricAllowed()){error("Entra con tu contraseña para habilitar la huella.");return;}biometric=new CancellationSignal();new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("Entrar a mi cuenta").setSubtitle("Solo en tu celular personal").setNegativeButton("Usar contraseña",getMainExecutor(),(d,w)->{}).build().authenticate(biometric,getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){task(()->{try{auth.refresh(true);}catch(java.io.IOException ignored){}PeerConfig.require(auth.biometricAllowed(),"Tu acceso cambió. Entra con tu usuario y contraseña.");StaffAccess.unlocked=auth.profile;return new JSONObject();},r->finishLogin());}@Override public void onAuthenticationError(int code,CharSequence text){error(text.toString());}});}
 private void finishLogin(){if(!auth.ready()){screen("Cuenta pendiente","Solicita tu usuario y contraseña a la cuenta maestra. Si ya tenías cuenta, debe configurar esa misma cuenta para conservar tu historial.");button("Iniciar sesión",this::login);button("Acceso privado de la cuenta maestra",this::masterSetup);return;}if(getIntent().getBooleanExtra("manage",false))dashboard();else complete();}
 private void complete(){setResult(RESULT_OK);finish();}
 private void switchCompany(){try{PeerConfig.require(new Vault(this,company).get("pending").isEmpty(),"Comprueba la entrega pendiente antes de cambiar de empresa.");stopService(new Intent(this,PeerService.class));Handler h=new Handler(getMainLooper());h.postDelayed(new Runnable(){int tries;public void run(){if(isFinishing()||isDestroyed())return;if(PeerService.running||PeerService.engine!=null){if(++tries<40){h.postDelayed(this,250);return;}error("La red aún se está cerrando. Vuelve a intentar.");return;}try{Companies.select(StaffActivity.this,company.equals("soboce")?"frigor":"soboce");startActivity(new Intent(StaffActivity.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}catch(Exception e){error(e.getMessage());}}},250);}catch(Exception e){error(e.getMessage());}}
 private void dashboard(){try{JSONObject g=auth.grant();screen("Mi cuenta",g.getString("name")+" · "+role(g.getString("role")));label("Usuario: "+g.optString("username","Pendiente de configurar"),16,Design.INK);label("Plantas: "+g.getJSONArray("plants").join(", ").replace("\"",""),15,Design.INK);
  if(auth.master()){button("Encargados y permisos",this::list);button("Mi usuario y contraseña",()->credentialsForm(g));}
  if(fingerprintAvailable()&&auth.profiles().length()==1&&auth.passwordCached()){CheckBox personal=new CheckBox(this);personal.setText("Es mi celular personal: entrar con huella");personal.setChecked(auth.biometricAllowed());page.addView(personal);personal.setOnCheckedChangeListener((v,on)->{try{auth.require("people","");auth.global.put("staffBiometric:"+auth.profile,on?"yes":"no");}catch(Exception e){error(e.getMessage());}});label("La huella es opcional y utiliza las biometrías registradas en Android. En un celular compartido utiliza contraseña.",13,Design.MUTED);}
  button("Actualizar mis permisos",()->task(()->auth.remote("status",new JSONObject()),r->{if(auth.authorized())dashboard();else{StaffAccess.lock();login();error("Tu cuenta se desactivó o inició sesión en otro celular.");}}));button("Cerrar sesión",()->{StaffAccess.lock();login();});button("Volver al comedor",this::complete);
 }catch(Exception e){StaffAccess.lock();login();error(e.getMessage());}}
 static String role(String r){return r.equals("master")?"Administradora principal (maestro)":r.equals("admin")?"Administrador":"Encargado";}
 private void list(){task(()->{PeerConfig.require(auth.master(),"Solo la cuenta maestra administra usuarios.");return auth.remote("list",new JSONObject());},r->{try{screen("Encargados y permisos","Crea usuarios y contraseñas aquí. Cada persona entra desde el login, sin solicitudes QR.");button("Crear usuario",()->form(null));JSONArray all=auth.users();for(int i=0;i<all.length();i++){JSONObject u=all.getJSONObject(i);if(u.optBoolean("deleted"))continue;if(u.getString("role").equals("master")){button(u.getString("name")+" · Cuenta maestra",()->credentialsForm(u));continue;}button(u.getString("name")+" · "+u.optString("username","Configurar contraseña")+(u.optBoolean("active")?"":" · Desactivado"),()->form(u));}button("Volver",this::dashboard);}catch(Exception e){error(e.getMessage());}});}
 private void form(JSONObject existing){try{
  PeerConfig.require(auth.master(),"Solo la cuenta maestra administra usuarios.");screen(existing==null?"Crear usuario":"Editar usuario","La cuenta y sus plantas corresponden a "+company.toUpperCase(Locale.ROOT)+". Los consumos anteriores se conservan.");
  EditText name=field("Nombre completo",existing==null?"":existing.getString("name"),false);
  EditText user=existing==null?field("Usuario","",false):null,pass=existing==null?password("Contraseña (mínimo 10 caracteres)"):null,again=existing==null?password("Repetir contraseña"):null;
  if(existing!=null)label("Usuario: "+existing.optString("username","Sin configurar"),16,Design.INK);
  Spinner roles=new Spinner(this);roles.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Encargado","Administrador"}));roles.setSelection(existing!=null&&existing.getString("role").equals("admin")?1:0);page.addView(roles);
  label("PLANTAS AUTORIZADAS",13,Design.BLUE);List<CheckBox> plants=new ArrayList<>();JSONArray all=config.seed.getJSONArray("plants");for(int i=0;i<all.length();i++){CheckBox c=new CheckBox(this);c.setText(all.getString(i));c.setChecked(existing!=null?StaffProtocol.contains(existing.getJSONArray("plants"),all.getString(i)):all.length()==1);plants.add(c);page.addView(c);}
  label("El encargado puede escanear, vincular obreros y consultar sus plantas. Permisos adicionales:",14,Design.MUTED);List<CheckBox> extras=new ArrayList<>();String[] keys={"issue","worker","visitor"},titles={"Emitir e imprimir QR físicos","Crear trabajadores","Autorizar visitantes"};for(int i=0;i<keys.length;i++){CheckBox c=new CheckBox(this);c.setText(titles[i]);c.setTag(keys[i]);c.setChecked(existing!=null&&StaffProtocol.contains(existing.getJSONArray("permissions"),keys[i]));extras.add(c);page.addView(c);}
  CheckBox active=new CheckBox(this);active.setText("Cuenta habilitada");active.setChecked(existing==null||existing.getBoolean("active"));active.setEnabled(existing!=null);page.addView(active);
  button(existing==null?"Crear usuario":"Guardar cambios",()->{try{JSONArray ps=new JSONArray(),perms=new JSONArray();for(CheckBox c:plants)if(c.isChecked())ps.put(c.getText().toString());for(CheckBox c:extras)if(c.isChecked())perms.put(c.getTag().toString());JSONObject body=new JSONObject().put("name",name.getText().toString()).put("role",roles.getSelectedItemPosition()==1?"admin":"encargado").put("plants",ps).put("permissions",perms).put("active",active.isChecked());String secret=existing==null?pass.getText().toString():"",repeat=existing==null?again.getText().toString():"";if(existing==null)body.put("username",user.getText().toString());else body.put("id",existing.getString("id")).put("expected",existing.getLong("revision"));
   task(()->{PeerConfig.require(auth.master(),"Solo la cuenta maestra administra usuarios.");if(body.getBoolean("active"))QrPrintData.requirePermission(Companies.license(this,company));if(existing==null){PeerConfig.require(secret.equals(repeat),"Las contraseñas no coinciden.");body.put("password",StaffPassword.credentials(secret));}return auth.remote(existing==null?"createAccount":"update",body);},r->{screen("Usuario guardado",existing==null?"Entrega el usuario y contraseña a esa persona por un medio privado. Puede entrar en su celular sin otra autorización.":"Los cambios se aplicarán en los teléfonos al sincronizar.");button("Volver a usuarios",this::list);});
  }catch(Exception e){error(e.getMessage());}});
  if(existing!=null){button(existing.has("username")?"Cambiar usuario o contraseña":"Configurar usuario y contraseña",()->credentialsForm(existing));button("Eliminar acceso",()->new AlertDialog.Builder(this).setTitle("Eliminar acceso de "+existing.optString("name")+"?").setMessage("Se impedirá entrar y se conservarán sus consumos e historial. Los teléfonos desconectados aplicarán la baja cuando sincronicen.").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar acceso",(d,w)->task(()->auth.remote("deleteAccount",new JSONObject().put("id",existing.getString("id")).put("expected",existing.getLong("revision"))),r->list())).show());}
  button("Cancelar",this::list);
 }catch(Exception e){error(e.getMessage());}}
 private void credentialsForm(JSONObject existing){try{PeerConfig.require(auth.master(),"Solo la cuenta maestra cambia contraseñas.");screen("Usuario y contraseña",existing.getString("name")+" · Se conserva esta cuenta y su historial. Una contraseña nueva requiere volver a entrar con internet.");EditText name=field("Usuario",existing.optString("username"),false),pass=password("Nueva contraseña (mínimo 10 caracteres)"),again=password("Repetir contraseña");button("Guardar contraseña",()->{String username=name.getText().toString(),secret=pass.getText().toString(),repeat=again.getText().toString();task(()->{PeerConfig.require(secret.equals(repeat),"Las contraseñas no coinciden.");QrPrintData.requirePermission(Companies.license(this,company));JSONObject credentials=StaffPassword.credentials(secret),reply=auth.remote("password",new JSONObject().put("id",existing.getString("id")).put("expected",existing.getLong("revision")).put("username",username).put("password",credentials));if(existing.getString("id").equals(auth.grant().getString("id")))auth.rememberPassword(credentials);return reply;},r->{screen("Contraseña guardada","El usuario puede entrar con su nueva contraseña. La contraseña no se muestra ni se puede consultar después de guardarla.");button("Volver a usuarios",this::list);});});button("Cancelar",this::dashboard);}catch(Exception e){error(e.getMessage());}}
 private void masterSetup(){screen("Acceso privado del maestro","Solo para la activación inicial o recuperación con el código privado del propietario. Los demás usuarios entran con su contraseña.");EditText name=field("Nombre del maestro","",false),pin=field("PIN temporal de 6 números","",true);button("Preparar recuperación privada",()->{String n=name.getText().toString(),p=pin.getText().toString();task(()->{auth.create(n,p,"recover");reload();return new JSONObject();},r->scanMaster());});button("Volver al login",this::login);}
 private void scanMaster(){new IntentIntegrator(this).setCaptureActivity(bo.colbert.credential.CredentialScanActivity.class).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Escanea el código privado de activación o recuperación del maestro").setBeepEnabled(false).setOrientationLocked(true).initiateScan();}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);IntentResult scan=IntentIntegrator.parseActivityResult(request,result,data);if(scan==null||scan.getContents()==null)return;try{String qr=scan.getContents();PeerConfig.require(qr.length()<16000&&qr.startsWith(StaffProtocol.MASTER),"Este no es el código privado del maestro.");JSONObject body=new JSONObject(qr.substring(StaffProtocol.MASTER.length()));JSONArray companies=body.getJSONArray("companies");String code="";for(int i=0;i<companies.length();i++)if(companies.getJSONObject(i).getString("cluster").equals(config.cluster))code=companies.getJSONObject(i).getString("code");PeerConfig.require(!code.isEmpty(),"Código de otra empresa.");String secret=code,action=body.optString("kind").equals("recovery")?"recover":"claim";task(()->auth.remote(action,new JSONObject().put("code",secret).put("name",auth.local().getString("name")).put("device",config.device)),r->dashboard());}catch(Exception e){error(e.getMessage());}}
 @Override protected void onDestroy(){if(biometric!=null)biometric.cancel();executor.shutdown();super.onDestroy();}
}
